:root{--t4b-red:#ef1725;--t4b-gold:#e8b82f;--t4b-bg:#030304;}
body{background:#030304!important}
.t4b-unity-hero{
  width:min(1840px,96vw);min-height:650px;margin:14px auto 0;position:relative;overflow:hidden;
  border:1px solid rgba(239,23,37,.28);background:#050506;display:flex;align-items:center;
}
.t4b-hero-bg{
  position:absolute;inset:0;background-image:url("data:image/png;base64,");
  background-size:cover;background-position:center center;filter:brightness(.84) saturate(.95);
}
.t4b-hero-shade{
  position:absolute;inset:0;background:
  linear-gradient(90deg,rgba(0,0,0,.80) 0%,rgba(0,0,0,.18) 46%,rgba(0,0,0,.10) 100%),
  linear-gradient(180deg,rgba(0,0,0,.04),rgba(0,0,0,.50));
}
.t4b-hero-content{position:relative;z-index:3;width:min(650px,43%);padding-left:4.5%;margin-top:-10px}
.t4b-eyebrow{font-size:10px;font-weight:900;letter-spacing:.18em;color:var(--t4b-gold);margin-bottom:12px}
.t4b-unity-hero h1{
  margin:0;font-size:clamp(58px,6.2vw,108px);line-height:.82;letter-spacing:-.06em;
  color:#f5f5f6;text-transform:uppercase;text-shadow:0 12px 40px rgba(0,0,0,.45);
}
.t4b-unity-hero h1 span{display:block;color:var(--t4b-gold);text-shadow:0 4px 20px rgba(232,184,47,.18)}
.t4b-unity-hero p{font-size:12px;letter-spacing:.16em;color:#d0d1d4;margin:22px 0}
.t4b-hero-actions{display:flex;gap:12px;flex-wrap:wrap}
.t4b-btn{
  padding:13px 18px;border:1px solid rgba(239,23,37,.65);font-size:9px;font-weight:900;
  letter-spacing:.08em;color:#fff;background:rgba(5,6,8,.72);backdrop-filter:blur(10px)
}
.t4b-btn-primary{background:linear-gradient(90deg,#8b0009,#ef1725);border-color:#ef1725}
.t4b-hero-bottom{
  position:absolute;z-index:3;bottom:18px;left:50%;transform:translateX(-50%);
  font-size:9px;letter-spacing:.35em;color:#8f9298;white-space:nowrap
}
.t4b-feature-grid{
  width:min(1840px,96vw);margin:0 auto 34px;display:grid;grid-template-columns:repeat(4,1fr);
  gap:12px;padding-top:12px
}
.t4b-card{height:178px;position:relative;overflow:hidden;border:1px solid rgba(239,23,37,.42);background:#08090b}
.t4b-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:brightness(.64) saturate(.9);transition:.4s ease}
.t4b-card-overlay{position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.82),rgba(0,0,0,.15))}
.t4b-card-copy{position:absolute;left:20px;top:20px;z-index:2}
.t4b-card h3{margin:0;color:#fff;font-size:24px;letter-spacing:-.03em}
.t4b-card p{margin:4px 0 0;color:#babcc1;font-size:9px;letter-spacing:.07em}
.t4b-card>span{position:absolute;right:18px;bottom:16px;z-index:2;color:#ef1725;font-size:28px}
.t4b-card:hover img{transform:scale(1.04);filter:brightness(.78) saturate(1)}
@media(max-width:900px){
  .t4b-unity-hero{min-height:620px}
  .t4b-hero-content{width:88%;padding:0 6%;margin-top:0}
  .t4b-feature-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:560px){
  .t4b-unity-hero{min-height:560px}
  .t4b-unity-hero h1{font-size:54px}
  .t4b-feature-grid{grid-template-columns:1fr}
}